//! Golden parity tests: every builtin theme resolved in Rust must equal the
//! output of the real `@opencode/theme` TypeScript pipeline, byte for byte
//! on every RGBA channel.
//!
//! Goldens were generated by `/tmp/opencode/theme-dump/dump.ts` (see the
//! theme-lane report): `<name>.<mode>.json` for every v1 asset (suffixed
//! `-v1`) and the v2 default theme. Five v1 themes collapse to a single dark
//! mode during migration, hence 63 goldens, not 68.

use std::fs;
use std::path::{Path, PathBuf};

use serde_json::{Value as Json, Value};

use oc_theme::builtins::{builtin_v1_theme, BUILTIN_V2_OPENCODE};
use oc_theme::{migrate_v1, parse_theme_document, resolve_theme_document, Mode};

fn goldens_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/goldens")
}

fn resolve_builtin(name: &str, mode: Mode) -> Json {
    let source = if let Some(v1_name) = name.strip_suffix("-v1") {
        let text =
            builtin_v1_theme(v1_name).unwrap_or_else(|| panic!("missing v1 asset {v1_name}"));
        (serde_json::from_str::<Json>(text).unwrap(), true)
    } else if name == "opencode" {
        (serde_json::from_str::<Json>(BUILTIN_V2_OPENCODE).unwrap(), false)
    } else {
        panic!("unknown golden theme name {name}");
    };
    let document = if source.1 {
        migrate_v1(&source.0).expect("v1 migration")
    } else {
        parse_theme_document(&source.0, name).expect("v2 parse")
    };
    let theme = resolve_theme_document(&document, Some(mode)).expect("resolve");
    let mut value = serde_json::to_value(&theme).unwrap();
    // generateSyntax runs against the base view in the TS pipeline.
    let base_styles = oc_theme::convert_theme_to_styles(&oc_theme::generate_syntax(&theme.tokens));
    if let Value::Object(map) = &mut value {
        map.insert("syntaxStyles".into(), serde_json::to_value(base_styles).unwrap());
    }
    value
}

/// Report the first differing path between two JSON values.
fn first_diff(expected: &Json, actual: &Json, path: &str, report: &mut Vec<String>) {
    match (expected, actual) {
        (Json::Object(a), Json::Object(b)) => {
            let mut keys: Vec<&String> = a.keys().chain(b.keys()).collect();
            keys.sort();
            keys.dedup();
            for key in keys {
                match (a.get(key), b.get(key)) {
                    (Some(e), Some(x)) => first_diff(e, x, &format!("{path}.{key}"), report),
                    (Some(_), None) => report.push(format!("{path}.{key}: missing in rust output")),
                    (None, Some(_)) => {
                        report.push(format!("{path}.{key}: unexpected in rust output"));
                    }
                    (None, None) => unreachable!(),
                }
            }
        }
        (Json::Array(a), Json::Array(b)) => {
            if a.len() != b.len() {
                report.push(format!("{path}: array length {} != {}", a.len(), b.len()));
            }
            for (index, (e, x)) in a.iter().zip(b.iter()).enumerate() {
                first_diff(e, x, &format!("{path}[{index}]"), report);
            }
        }
        (a, b) if a == b => {}
        (a, b) => report.push(format!("{path}: golden {a} != rust {b}")),
    }
}

fn golden_files() -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = fs::read_dir(goldens_dir())
        .expect("goldens directory")
        .filter_map(|entry| entry.ok().map(|e| e.path()))
        .filter(|path| path.extension().is_some_and(|ext| ext == "json"))
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no goldens found");
    files
}

#[test]
fn golden_parity_all_builtin_themes() {
    let mut failures = Vec::new();
    let mut passed = 0;
    let files = golden_files();
    assert_eq!(files.len(), 63, "expected 63 goldens (34 assets, 5 single-mode)");

    for file in &files {
        let stem = file.file_stem().unwrap().to_string_lossy().to_string();
        let (name, mode) = stem.rsplit_once('.').expect("golden file named <name>.<mode>");
        let mode = Mode::from_name(mode).expect("golden mode");
        let golden: Json = serde_json::from_str(&fs::read_to_string(file).unwrap()).unwrap();
        let actual = resolve_builtin(name, mode);
        if golden == actual {
            passed += 1;
            continue;
        }
        let mut report = Vec::new();
        first_diff(&golden, &actual, "$", &mut report);
        failures.push(format!(
            "{stem}: {} mismatches, first few:\n  {}",
            report.len(),
            report.iter().take(6).cloned().collect::<Vec<_>>().join("\n  ")
        ));
    }

    assert!(
        failures.is_empty(),
        "golden parity failures ({}/{} passed):\n{}",
        passed,
        files.len(),
        failures.join("\n")
    );
}

#[test]
fn builtin_theme_counts() {
    assert_eq!(oc_theme::builtins::BUILTIN_V1_THEMES.len(), 33);
    assert_eq!(oc_theme::builtins::builtin_v1_names().len(), 33);
    // Every v1 asset migrates and resolves in both modes it declares.
    for (name, source) in oc_theme::builtins::BUILTIN_V1_THEMES {
        let json = serde_json::from_str::<Json>(source).unwrap();
        let document = migrate_v1(&json).expect(name);
        for mode in document.modes() {
            let theme = resolve_theme_document(&document, Some(mode)).expect(name);
            assert!(theme.tokens.hue.len() >= 3, "{name} hue map");
        }
    }
    let json = serde_json::from_str::<Json>(BUILTIN_V2_OPENCODE).unwrap();
    let document = parse_theme_document(&json, "opencode").unwrap();
    assert_eq!(document.modes(), vec![Mode::Light, Mode::Dark]);
}
